import math
import re
from fractions import Fraction

_NUM = r'(\d+(?:\.\d+)?|\.\d+)'
_COMPONENT = re.compile(_NUM + r'\s*([A-Za-z]+)')
_CLOCK_FIELD = re.compile(r'\d+(?:\.\d+)?')
_ISO = re.compile(
    r'P(?:' + _NUM + r'W)?(?:' + _NUM + r'D)?'
    r'(?:T(?:' + _NUM + r'H)?(?:' + _NUM + r'M)?(?:' + _NUM + r'S)?)?',
    re.IGNORECASE,
)

_UNITS = {
    'second': 1, 'seconds': 1, 'sec': 1, 'secs': 1, 's': 1,
    'minute': 60, 'minutes': 60, 'min': 60, 'mins': 60, 'm': 60,
    'hour': 3600, 'hours': 3600, 'hr': 3600, 'hrs': 3600, 'h': 3600,
    'day': 86400, 'days': 86400, 'd': 86400,
    'week': 604800, 'weeks': 604800, 'wk': 604800, 'wks': 604800, 'w': 604800,
}


def _to_seconds(total: Fraction) -> int:
    # round half up to the nearest whole second
    return math.floor(total + Fraction(1, 2))


def _frac(s):
    return Fraction(s)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r'\d+', s):
        return int(s)

    if ':' in s:
        parts = s.split(':')
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(_CLOCK_FIELD.fullmatch(p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        total = Fraction(0)
        for p in parts:
            total = total * 60 + _frac(p)
        return _to_seconds(total)

    if s[0] in 'Pp':
        m = _ISO.fullmatch(s)
        if not m or s[1:] == '' or s[-1] in 'Tt':
            raise ValueError(f"invalid ISO duration: {text!r}")
        groups = m.groups()
        weights = [604800, 86400, 3600, 60, 1]
        if all(g is None for g in groups):
            raise ValueError(f"invalid ISO duration: {text!r}")
        # a 'T' with no time components is invalid
        if 'T' in s.upper() and all(g is None for g in groups[2:]):
            raise ValueError(f"invalid ISO duration: {text!r}")
        total = Fraction(0)
        for g, w in zip(groups, weights):
            if g is not None:
                total += _frac(g) * w
        return _to_seconds(total)

    total = Fraction(0)
    pos = 0
    n = len(s)
    while True:
        while pos < n and s[pos].isspace():
            pos += 1
        if pos >= n:
            break
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += _frac(m.group(1)) * _UNITS[unit]
        pos = m.end()
    return _to_seconds(total)

